// Generated bytes for D1 media are available only through the guarded API.
// Normalize encoded prefixes before consulting ASSETS, including duplicate slashes.
export function privatePhotoPath(path){
 for(let i=0;i<3;i++){if(path.replace(/\/{2,}/g,'/').startsWith('/_photo-variants/'))return true;try{const decoded=decodeURIComponent(path);if(decoded===path)break;path=decoded;}catch{break;}}
 return path.replace(/\/{2,}/g,'/').startsWith('/_photo-variants/');
}
